// SK-F-04 — vector similarity search latency (validates KF-04, KNF-01).
// 100 RPS for 5 min against Qdrant (the Feast online store backing the
// sentiment embeddings); p50 < 5 ms, p95 < 8 ms, p99 < 10 ms (KNF-01).
// Top-10 recall (> 0.95) is verified separately against the offline ground
// truth.
//
// Embeddings are generated by the `vector-embedding` CronJob and written to
// Qdrant through Feast; this script queries Qdrant's REST Query API directly
// (POST /points/query, current as of Qdrant v1.10+) with a precomputed query
// vector (random here — recall is checked elsewhere).
//
// Note: Qdrant lives in the `storage` namespace behind a default-deny
// NetworkPolicy; allow platform-test → qdrant:6333 before running.
//
// Run:
//   k6 run -e QDRANT_URL=http://qdrant.storage.svc:6333 \
//          -e COLLECTION=crypto_sentiment -e VECTOR_DIM=768 \
//          load/vector-search-latency.js
import http from 'k6/http';
import { check } from 'k6';

const QDRANT_URL = __ENV.QDRANT_URL || 'http://qdrant.storage.svc:6333';
const COLLECTION = __ENV.COLLECTION || 'crypto_sentiment';
const VECTOR_DIM = Number(__ENV.VECTOR_DIM || 768);

export const options = {
  scenarios: {
    vsearch: {
      executor: 'constant-arrival-rate',
      rate: Number(__ENV.RPS || 100),
      timeUnit: '1s',
      duration: __ENV.DURATION || '5m',
      preAllocatedVUs: 50,
      maxVUs: 500,
    },
  },
  thresholds: {
    http_req_duration: ['p(50)<5', 'p(95)<8', 'p(99)<10'],
    http_req_failed: ['rate<0.001'],
  },
};

function randomVector(dim) {
  const v = new Array(dim);
  for (let i = 0; i < dim; i++) v[i] = Math.random() * 2 - 1;
  return v;
}

export default function () {
  const body = JSON.stringify({
    query: randomVector(VECTOR_DIM),
    limit: 10,
    with_payload: false,
  });
  const res = http.post(
    `${QDRANT_URL}/collections/${COLLECTION}/points/query`,
    body,
    { headers: { 'Content-Type': 'application/json' } }
  );
  check(res, { 'status is 200': (r) => r.status === 200 });
}
